import re, zipfile
from xml.etree import ElementTree as ET

M = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
NS = {"m": M}
PATH = "sales_data.xlsx"

with zipfile.ZipFile(PATH) as z:
    entries = {n: z.read(n) for n in z.namelist()}

sheet = ET.fromstring(entries["xl/worksheets/sheet1.xml"])
rows = sheet.findall(".//m:sheetData/m:row", NS)

def col_letter(ref):
    return re.match(r"[A-Z]+", ref).group(0)

values = {}
formulas = {}
for row in rows:
    for c in row.findall("m:c", NS):
        ref = c.get("r")
        f = c.find("m:f", NS)
        v = c.find("m:v", NS)
        if f is not None:
            formulas[ref] = f.text or ""
        if v is not None and v.text not in (None, ""):
            values[ref] = v.text if c.get("t") == "str" else float(v.text)
        else:
            values[ref] = None

def resolve(ref):
    if values.get(ref) is not None:
        return values[ref]
    if ref in formulas:
        values[ref] = evaluate(ref)
        return values[ref]
    return None

def evaluate(ref):
    return eval_expr(formulas[ref])

def eval_expr(expr):
    expr = expr.strip()
    m = re.fullmatch(r"IFERROR\((.+),(.+)\)", expr)
    if m:
        try:
            return eval_expr(m.group(1))
        except ZeroDivisionError:
            return ""
    m = re.fullmatch(r"SUM\(([A-Z]+\d+):([A-Z]+\d+)\)", expr)
    if m:
        col = col_letter(m.group(1))
        r0 = int(re.search(r"\d+", m.group(1)).group())
        r1 = int(re.search(r"\d+", m.group(2)).group())
        return sum(resolve(f"{col}{r}") for r in range(r0, r1 + 1))
    return eval_arith(expr)

def eval_arith(expr):
    tokens = re.findall(r"\(|\)|[A-Z]+\d+|\+|-|\*|/|[0-9.]+", expr)
    pos = [0]
    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None
    def advance():
        t = tokens[pos[0]]
        pos[0] += 1
        return t
    def primary():
        t = advance()
        if t == "(":
            v = add()
            advance()
            return v
        if re.fullmatch(r"[A-Z]+\d+", t):
            return resolve(t)
        return float(t)
    def mul():
        v = primary()
        while peek() in ("*", "/"):
            op = advance()
            rhs = primary()
            v = v * rhs if op == "*" else v / rhs
        return v
    def add():
        v = mul()
        while peek() in ("+", "-"):
            op = advance()
            rhs = mul()
            v = v + rhs if op == "+" else v - rhs
        return v
    return add()

cached = {}
for ref in list(formulas):
    if values[ref] is None:
        cached[ref] = evaluate(ref)
        values[ref] = cached[ref]

raw = entries["xl/worksheets/sheet1.xml"].decode("utf-8")
for ref, val in cached.items():
    if isinstance(val, str):
        continue
    num = repr(val)
    pat = re.compile(r'(<c r="' + ref + r'"[^>]*><f>[^<]*</f>)<v />')
    raw, n = pat.subn(r"\1<v>" + num + r"</v>", raw)
    assert n == 1, f"pattern mismatch for {ref}"

