with zipfile.ZipFile(PATH) as z:
    assert z.testzip() is None, "zip integrity failed"
    sh = ET.fromstring(z.read("xl/worksheets/sheet1.xml"))
    print("computed cached values:")
    for row in sh.findall(".//m:sheetData/m:row", NS):
        line = []
        for c in row.findall("m:c", NS):
            v = c.find("m:v", NS)
            f = c.find("m:f", NS)
            line.append((c.get("r"), (f.text if f is not None else None), (v.text if v is not None else None)))
        print(line)
    errs = ["#VALUE!", "#DIV/0!", "#REF!", "#NAME?", "#NULL!", "#NUM!", "#N/A"]
    found = []
    for row in sh.findall(".//m:sheetData/m:row", NS):
        for c in row.findall("m:c", NS):
            v = c.find("m:v", NS)
            if v is not None and v.text and any(e in v.text for e in errs):
                found.append((c.get("r"), v.text))
    print("errors found:", found)

